package com.tekwatt.payment.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="payment_gateway_configs",uniqueConstraints=@UniqueConstraint(columnNames={"tenant_id","provider"}))public class PaymentGatewayConfig{@Id private UUID id;@Column(nullable=false)private UUID tenantId;@Column(nullable=false,length=40)private String provider;@Column(nullable=false)private boolean enabled;@Column(length=255)private String publicKey;@Column(length=500)private String secretKey;@Column(length=120)private String upiVpa;@Column(length=120)private String payeeName;@Column(nullable=false)private Instant updatedAt;protected PaymentGatewayConfig(){}public PaymentGatewayConfig(UUID t,String p){id=UUID.randomUUID();tenantId=t;provider=p;updatedAt=Instant.now();}public void update(boolean e,String pub,String secret,String upi,String payee){enabled=e;publicKey=pub;if(secret!=null&&!secret.isBlank())secretKey=secret;upiVpa=upi;payeeName=payee;updatedAt=Instant.now();}public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public String getProvider(){return provider;}public boolean isEnabled(){return enabled;}public String getPublicKey(){return publicKey;}public boolean hasSecret(){return secretKey!=null&&!secretKey.isBlank();}public String getUpiVpa(){return upiVpa;}public String getPayeeName(){return payeeName;}public Instant getUpdatedAt(){return updatedAt;}}
